import{_ as n,C as o,o as s,c as e,j as i,E as l,a as r,a3 as d}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (Cyber)","link":"/mentor/10-sinf-cyber/"},"n":2,"bob":"I-bob · Kiberxavfsizlikka kirish","lessons":[{"g":4,"title":"CIA uchligi (1-qism): konfidensiallik, yaxlitlik va foydalanuvchanlik tamoyillari","lead":"CIA uchligi (1-qism): konfidensiallik, yaxlitlik va foydalanuvchanlik tamoyillari","link":"/mentor/10-sinf-cyber/hafta-02/dars-1","slide":"/slaydlar/10-sinf-cyber/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-cyber/hafta-02/dars-1-test.html"},{"g":5,"title":"CIA uchligi (2-qism): CIA buzilish ssenariylari va MITM hujumlari","lead":"[!CAUTION]","link":"/mentor/10-sinf-cyber/hafta-02/dars-2","slide":"/slaydlar/10-sinf-cyber/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-cyber/hafta-02/dars-2-test.html"},{"g":6,"title":"Xavfsizlikni anglash (1-qism): xavfsizlik tafakkuri va kuchli parollar siyosati","lead":"«Xavfsizlik o'ziga xos fikrlash tarzini talab qiladi. Yaxshi mutaxassislar do'konga kirsa qanday o'g'irlik qilish mumkinligini, kompyuter ko'rsa qanday zaiflik borligini o'ylamasdan turolmaydilar.» — **Bryus Shnayer**","link":"/mentor/10-sinf-cyber/hafta-02/dars-3","slide":"/slaydlar/10-sinf-cyber/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-cyber/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-cyber/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-cyber/hafta-02/index.md","filePath":"mentor/10-sinf-cyber/hafta-02/index.md"}`),h={name:"mentor/10-sinf-cyber/hafta-02/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},k={class:"blk"},y={id:"baholash-mezoni",tabindex:"-1"};function b(c,a,f,g,v,q){const t=o("Icon");return s(),e("div",null,[i("div",u,[i("h2",m,[l(t,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=d('<p>Ushbu haftada o&#39;tilgan darslar bo&#39;yicha mustaqil amaliy uyga vazifalar ro&#39;yxati:</p><hr><h2 id="_4-dars-cia-uchligi-konfidensiallik-yaxlitlik-va-foydalanuvchanlik-tamoyillari" tabindex="-1">4-dars. CIA uchligi: konfidensiallik, yaxlitlik va foydalanuvchanlik tamoyillari <a class="header-anchor" href="#_4-dars-cia-uchligi-konfidensiallik-yaxlitlik-va-foydalanuvchanlik-tamoyillari" aria-label="Permalink to &quot;4-dars. CIA uchligi: konfidensiallik, yaxlitlik va foydalanuvchanlik tamoyillari&quot;">​</a></h2><ol><li>O&#39;zingiz qiziqqan ikkita sohani tanlang (masalan: Elektron tijorat sayti va Tez tibbiy yordam dispetcherlik xizmati).</li><li>Ushbu ikki soha uchun CIA uchligini (C, I, A) taqqoslang va har biri uchun qaysi mezon birinchi o&#39;rinda turishini, nima sababdan shunday ekanligini 4-5 jumla bilan yozing.</li><li>Kompyuteringizda ixtiyoriy matnli fayl yarating va uning SHA-256 xeshini oling (<code>sha256sum</code> yoki <code>CertUtil -hashfile</code>). Matnga bitta probel yoki nuqta qo&#39;shib qayta xesh oling va ikkala natijani daftaringizga ko&#39;chirib solishtiring.</li></ol><hr><h2 id="_5-dars-cia-buzilish-ssenariylari-va-mitm-hujumlari" tabindex="-1">5-dars. CIA buzilish ssenariylari va MITM hujumlari <a class="header-anchor" href="#_5-dars-cia-buzilish-ssenariylari-va-mitm-hujumlari" aria-label="Permalink to &quot;5-dars. CIA buzilish ssenariylari va MITM hujumlari&quot;">​</a></h2><ol><li>O&#39;rtadagi odam (MITM) hujumi qanday qilib bir vaqtning o&#39;zida ham Konfidensiallikka, ham Yaxlitlikka putur yetkazishi mumkinligini ssenariy asosida tushuntiring.</li><li>Nima sababdan kafe yoki aeroportlardagi ochiq jamoat Wi-Fi tarmoqlarida parollarni kiritish xavfli va nima uchun bunday holatlarda VPN ishlatish zarur?</li><li>Tarmoq kommutatorlarida Dynamic ARP Inspection (DAI) texnologiyasi qanday ishlashini konspektdan foydalanib yozma bayon eting.</li></ol><hr><h2 id="_6-dars-xavfsizlik-tafakkuri-va-kuchli-parollar-siyosati" tabindex="-1">6-dars. Xavfsizlik tafakkuri va kuchli parollar siyosati <a class="header-anchor" href="#_6-dars-xavfsizlik-tafakkuri-va-kuchli-parollar-siyosati" aria-label="Permalink to &quot;6-dars. Xavfsizlik tafakkuri va kuchli parollar siyosati&quot;">​</a></h2><ol><li>Xavfsizlik tafakkurining 5 ta tamoyilidan (What could go wrong, Adversarial, Defensive, Assume breach, Know assets) birini tanlang va unga kundalik hayotingizdan bitta misol keltiring.</li><li><code>haveibeenpwned.com/Passwords</code> xizmatiga kiring (yoki Kaspersky Password Checker) va ilgari ishlatgan oddiy so&#39;zli parollaringiz (masalan: <code>123456</code>, <code>qwerty2020</code>) necha marta buzilgan bazalarda topilganini tekshiring.</li><li>O&#39;zingiz uchun kamida 14 belgidan iborat, katta-kichik harflar, sonlar va belgilarni o&#39;z ichiga olgan namunaviy kuchli parol formulasini ishlab chiqing (masalan: sevimli she&#39;r yoki iboraning bosh harflari asosida: <code>M@kt@b2025#Oqish</code>).</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-100-ballik-tizim" tabindex="-1">Baholash mezonlari (100 ballik tizim) <a class="header-anchor" href="#baholash-mezonlari-100-ballik-tizim" aria-label="Permalink to &quot;Baholash mezonlari (100 ballik tizim)&quot;">​</a></h3><ol><li><p><strong>CIA triadasi va sohalar tahlili (30 ball):</strong></p><ul><li>Confidentiality, Integrity, Availability mohiyatini to&#39;g&#39;ri tushuntirishi (10 ball);</li><li>Sohalar bo&#39;yicha ustuvorliklarni (bankda Integrity, 103 da Availability) to&#39;g&#39;ri asoslay olishi (10 ball);</li><li>Xesh funksiyasi (SHA-256) yaxlitlikni qanday tasdiqlashini amalda ko&#39;rsatishi (10 ball).</li></ul></li><li><p><strong>MITM va tarmoq xavfsizligi (30 ball):</strong></p><ul><li>ARP Spoofing va Man-in-the-Middle ishlash mexanizmini to&#39;g&#39;ri ifodalashi (10 ball);</li><li>HTTPS va VPN ning MITM ga qarshi qanday himoya qilishini anglashi (10 ball);</li><li>Statik ARP va DAI usullarini to&#39;g&#39;ri tushuntirishi (10 ball).</li></ul></li><li><p><strong>Xavfsizlik tafakkuri va parollar siyosati (40 ball):</strong></p><ul><li>Security Mindset tamoyillarini (hujumchi va himoyachi kabi fikrlash) to&#39;g&#39;ri qo&#39;llay olishi (15 ball);</li><li>Nmap va Hydra vositalarining maqsad va vazifalarini bilishi (15 ball);</li><li>Kuchli parol mezonlari va parol menejerlarining ahamiyatini to&#39;g&#39;ri ochib berishi (10 ball).</li></ul></li></ol><h3 id="kutiladigan-namunaviy-natijalar" tabindex="-1">Kutiladigan namunaviy natijalar <a class="header-anchor" href="#kutiladigan-namunaviy-natijalar" aria-label="Permalink to &quot;Kutiladigan namunaviy natijalar&quot;">​</a></h3><ul><li>O&#39;quvchi xesh kodining bitta harf o&#39;zgarganda butunlay o&#39;zgarishini o&#39;z ko&#39;zi bilan ko&#39;rgan bo&#39;lishi kerak;</li><li>Parol menejerlaridan foydalanish zarurligini va ochiq Wi-Fi da VPN o&#39;rnini to&#39;liq tushungan bo&#39;lishi lozim.</li></ul>',16))]),i("div",k,[i("h2",y,[l(t,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=d('<p><strong>Mavzular:</strong></p><ol><li>CIA uchligi (1-qism): konfidensiallik, yaxlitlik va foydalanuvchanlik tamoyillari</li><li>CIA uchligi (2-qism): CIA buzilish ssenariylari va MITM hujumlari</li><li>Xavfsizlikni anglash (1-qism): xavfsizlik tafakkuri va kuchli parollar siyosati</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>CIA Triadasi</strong></td><td>Confidentiality, Integrity, Availability mohiyati, SHA-256 xesh tahlili</td><td>30 ball</td></tr><tr><td><strong>MITM va Tarmoq</strong></td><td>ARP Spoofing mexanizmi, arpspoof, Wiresharkda HTTP tahlili, DAI va VPN</td><td>30 ball</td></tr><tr><td><strong>Tafakkur &amp; Parollar</strong></td><td>Security Mindset tamoyillari, Nmap va Hydra tahlili, Bitwarden va kuchli parollar</td><td>40 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>CIA triadasi (30)</th><th>MITM &amp; Tarmoq (30)</th><th>Tafakkur &amp; Parol (40)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar ko&#39;pincha ARP protokoli nega himoyalanmaganligini va MITM paytida IP Forwarding yoqilmasa nima sababdan internet uzilib qolishini tushunishda qiyinchilikka duch kelishlari mumkin. Ushbu jarayonni doskada paketlar yo&#39;nalishi bilan chizib ko&#39;rsating.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> Wireshark filtrlari (masalan, <code>arp.duplicate-address-frame</code> yoki <code>tcp.flags.syn == 1 and tcp.flags.ack == 0</code>) orqali tarmoqda anomal harakatlarni avtomatik aniqlash amaliyotini berish tavsiya etiladi.</li></ul>',11))])])}const x=n(h,[["render",b]]);export{p as __pageData,x as default};
